P["LR3-002"] = ("出师得胜 positive：总镇奉命出师江东，课式元首炎上、三传午（贵人）寅（勾陈）戌（太常），贵人居初传临事、火势炎上主军威进取，寅午戌火局助势，主此行建功得胜、凯旋受赏。应期以月档论，午月午日为捷报主坐标。", "陈东明出师一课，课式元首、炎上先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：大六壬兵斗门断；丙子年二月辛巳日，三传午（贵人）寅（勾陈）戌（太常）自成寅午戌火局，兵斗门贵人领传、火局炎上主锐进得地；申酉空、辰巳落空，巳为日支落空主初行小滞不碍大势。应期三路：逢值午、逢冲子、填实巳，取午路与胜局同向，余舍。", 0.58, NT)
P["LR3-004"] = ("功名迟成 positive：仇庸足功名前程，八专曲直、三传亥（螣蛇）卯（玄武）未（青龙），木局曲直成势而末传青龙入墓于未，主功名有成但迟滞暗耗在前，须待青龙出墓之运年方显。应期以年档论，主坐标取卯年卯月一线。", "仇庸足功名一课，课式八专、曲直先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：大六壬仕宦门断；辛未年四月己未日，三传亥卯未木局全，曲直主仁途文进，末传未为日干本家乘青龙主终得禄位，惟初传螣蛇、中传玄武主先有惊扰暗失；子丑空、辰巳落空不碍三传。应期三路：逢值卯、逢合未、出空子丑，年档取卯路，余舍。", 0.54, NT)
P["LR3-006"] = ("仕途升进 positive：贺中令任台垣占仕途，三传巳（贵人）寅（六合）亥（天空）与行人护行课同式，贵人领传、六合居中主同僚相得，主仕途平稳而有升迁之望；末传亥水天空主晚段一任虚衔，升而不久。应期以月档论，巳月巳日为主坐标。", "贺中令仕途一课，课式元首、玄胎先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：大六壬仕宦门断；癸酉年八月壬戌日，三传巳（贵人）寅（六合）亥（天空），壬水日干以巳为财、寅为食伤生财、贵人乘财领传主因职得禄，仕宦门贵人初传为升象首据；子丑空、酉戌落空，戌支落空主现任未稳、动而后升。应期三路取贵人逢值巳路，余舍。两段式：近段升（贵人据）、远段亥天空只主一任虚衔量级下调，不断反向终局。", 0.55, NT)
P["LR3-008"] = ("功名难成 negative：孙兴功自占功名，课式八专铸印绝嗣、三传巳（白虎）戌（朱雀）卯（太阴），白虎领传主阻丧之气、朱雀中传主文书口舌，末传卯木太阴暗耗，主此番功名无成，并防因文书招祸。应期以年档论，只断方向、不报得名之期。", "孙兴功功名一课，课式八专、铸印、绝嗣先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：大六壬仕宦门断；辛巳年十月己未日，三传巳（白虎）戌（朱雀）卯（太阴），巳火为己土印星本主文书功名，然乘白虎则印化为阻，铸印课名与绝嗣并见主印信虽铸而后继无人之象；子丑空、巳午落空，初传巳又落空，功名之据落空为决定性证据。应期三路无一指向得名，明写无候选故不报期。", 0.56, NT)
P["LR3-010"] = ("此官获罪去位 negative：代占在朝官员，课式玄胎伏吟、三传巳（朱雀）申（天后）寅（青龙），伏吟主停滞自刑、朱雀领传主文书弹章临身，主此官将因文书言事获罪、贬谪去位，青龙末传只主去位后尚有转任余地。应期以月档论，巳月巳日为发难主坐标。", "代占在朝官员一课，课式玄胎、伏吟先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：大六壬仕宦兼公讼门断；辛未年四月戊午日，伏吟课干支皆自临主静极思动而自招其咎，初传巳火朱雀为戊土之印化文书乘朱雀成弹章之象，中传申金天后泄气，末传寅木青龙为戊之官星主终局仍系于官位得失；子丑空两落。应期三路：逢值巳、逢冲亥、逢合申，取巳路定发难期，余舍。对象核对：应验对象为所代占之在朝官员，非占者本人。", 0.54, NT)
P["LR3-101"] = ("会试不中 negative：刘若宜会试，三传酉（天后）戌（太阴）亥（玄武）连茹阴进，无官星贵人青龙入传，朱雀文书之神不现，主今科榜上无名；连茹递进只主再接再厉、次科可期。应期以年档论，本科放榜即验、不中不报中式之期。", "刘若宜会试一课，课式蒿矢、连茹先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：大六壬会试门断；丁丑年二月乙未日，三传酉戌亥皆阴支顺进，乙木日干以酉为杀、亥为印，印星亥水居末传乘玄武主文名暗昧，官星辛金不入传、朱雀不现，会试门以官印朱雀三者缺二为落第之据；辰巳空、巳午落空，午为朱雀之位落空更证文书无功。应期三路无中式候选，明写不报。", 0.57, NT)
P["LR3-104"] = ("上疏得允 positive：王旋官上疏，初传酉金勾陈主章奏先经稽核勾留，中传丑土太常主常典可据，末传巳火贵人临收束，主疏虽迟滞终蒙采纳、本人因疏得进。应期以月档论，巳月巳日贵人逢值为主坐标。", "王旋官上疏一课，课式从革、绝嗣先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：大六壬章奏门断；辛未年六月癸卯日，三传酉（勾陈）丑（太常）巳（贵人），癸水日干以巳为财、贵人乘之居末主君恩终至，章奏门末传见贵人为得旨之据；辰巳空、申酉落空，初传酉落空主疏初上如石沉、须待巳位贵人填动而行。应期三路：逢值巳、逢冲亥、出空酉，取巳路，余舍。", 0.54, NT)
P["LR3-107"] = ("此人主凶暗 negative：埂子街来客，三传子（天后）亥（太阴）戌（玄武）递退阴水成群、玄武收尾，主此人非坦途君子之象——系行踪暗昧、涉讼逃或负累之人，吉凶主凶，近之防受牵累。应期以月档论，子月子日为应验主坐标。卡面课式首字残泐存疑，已注明。", "寓中来客射人一课，课式退茹（卡面注原书课体首字疑残泐存疑）先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：大六壬公讼兼射覆式断人；壬午年七月甲午日，三传子亥戌退茹而下、水势阴盛，甲木日干泄于水、戌土玄武为暗昧盗讼之象，公讼门玄武末传主其人有未了之讼累；辰巳空、卯辰落空。输入残损：课式一字残泐，不臆补，在此注明并略降置信。应期三路取逢值子路，余舍。", 0.48, NT)
P["LR3-110"] = ("失马可得 positive：王怀荫失马，三传卯（朱雀）戌（白虎）巳（贵人），卯戌相合主马为人收留栓系，末传贵人主终有人送回或指引寻得；寻向以卯戌之方（东与西北合参、主向东）为先。应期以日档论（失物近事、日尺度有据）：窗口旬内，主坐标取卯日，次取巳日贵人逢值。", "王怀荫失马一课，课式知一、斫轮先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：大六壬走失门断；庚寅年十月癸卯日，三传卯（朱雀）戌（白虎）巳（贵人），走失门以類神马取午而午不入传、改以三传合局断：卯戌合主物有所系不远行，贵人末传主得人助还；辰巳空、亥子落空，巳传落空主归期稍迟。应期三路：逢值卯、逢合戌、逢值巳，日档取卯为主坐标、巳为送回之续据并留舍取理由。对象核对：应验对象为所失之马本身，非其主人。", 0.55, NT)
P["LR3-112"] = ("病可愈 positive：刘一纯占病，课式元首润下、三传辰（玄武）申（青龙）子（螣蛇），中传申金青龙为日干之生源（申子辰水局润下主药力流通），主病可治愈；末传子水螣蛇主愈后仍有一段惊忧缠绵。应期以月档论，申月申日为主坐标。对象复述：主语为刘一纯本人。", "刘一纯占病一课，课式元首、润下先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：大六壬疾病门断；辛未年正月戊申日，三传辰（玄武）申（青龙）子（螣蛇）成申子辰水势，戊土日干赖辰申之间金水泄秀通关，疾病门中传青龙为生机之据；寅卯空、午未落空，午为戊之印落空主调养须久。应期三路：逢值申、逢合辰、出空午，取申路定向，余舍。两段式：近段药力通（青龙据），远段螣蛇末传只主缠绵量级，不断反向。", 0.54, NT)
P["LR3-114"] = ("鸦鸣主凶信 negative：僧敏若夜闻鸦鸣，三传子（太常）亥（玄武）戌（太阴）退茹阴沉、玄武居中，主此鸣应于近处丧病或失盗之信，非吉兆；应验对象为庵外近邻一户人家之事，非僧本人大祸。应期以日档论（应候近事、日尺度有据）：窗口旬内，主坐标取子日，次亥日。", "僧敏若鸦鸣一课，课式重审、退茹先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：大六壬应候门断；己丑年三月乙丑日丁亥时，三传子（太常）亥（玄武）戌（太阴）皆阴将阴支，应候门夜鸣以玄武太阴主暗昧凶信，乙木日干泄于子亥水而无阳神照临；戌亥空、酉戌落空，末传戌落空主凶信虽至而祸不临占者本身——对象定位据此把应验对象落在近邻而非庵僧本人。应期三路取逢值子路，余舍。", 0.50, NT)
P["LR3-116"] = ("射覆断物：范玄同袖帨所包之物，断为布帛包裹的银钱类小件——金属圆形之物一枚或数枚（银钱/银锭之属），非文书、非食物。置信低：三传天干未载、旬空未载，盘面残损。应期不适用（射覆无应期，只断物象）。", "范玄同袖帨射覆一课，课式八专先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：大六壬射覆门断；辛巳年八月甲寅日，三传丑（贵人）亥（太阴）亥（太阴），丑土为金库、贵人乘之主贵重金属之器，亥水太阴两见主藏匿柔物包裹，射覆门以库神乘贵断银钱之属；输入残损：卡面明载三传后两传天干未载、原书未载旬空，不臆补，在此注明并降置信。", 0.30, NT)
P["LY-001"] = ("终有官 positive（终局单判）：将来有官否——初占兑化讼官鬼巳火动而月破、五爻父母未土动，再占水地比官鬼卯木持世，两卦合断主官终可得而非速得：初卦主先有破耗争议、后卦官临世身自就之。应期双层：窗口以年档计，主坐标取卯年（比卦官星逢值），巳年为初动之续验。", "占将来有官否一题，初占兑为泽之天水讼、再占水地比静卦两卦并陈先行；system=liuyao（卡面逐字，字段名为 system）；亥月己丑日，初卦官鬼巳火临月破动而无力速成、父母未土动主文书先行，再占比卦官鬼卯木持世为官就身之象，两卦分工：初卦定迟与破、再占定终得。动化方向：巳火动化午火进而不退；反转条件：比卦官星受冲破则翻，无此据。应期三步：尺度年档（仕途问年），三路逢值卯、填实巳、冲实丑，取卯路与终局同向。终局依通则单判为有官，不以 mixed 收束。", 0.55, T(True, False, False, "初卦兑化讼之变卦结构参与定迟破、再占为主断故 changed_main 取初卦变象一义并在此留痕；两卦皆明现官星无伏神；卡面两卦读法无争议注记"))
P["LY-002"] = ("父归有期 positive（终局单判）：占父何日归，上爻父母戌土动持世、化未土退归本位，主父已在归途、归期在即。应期双层：窗口数日内（行人近归、日档有据），主坐标取戌日（用神逢值动而应归），次取未日化爻逢值。对象复述：断语主语为占者之父，父母戌土即其指代。", "占父何日归一题，卦乾为天之泽天夬、上爻父母戌土○动先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：六爻纳甲行人门断；辰月戊子日父母戌土得辰月冲动（暗动与明动并见）主行人已动身，子日水空（子为空亡与否依旬，卡面未注旬空、不臆断）不碍戌土值日应归。动化方向：戌化未为退神主归家收束向吉；反转条件：父母化破则翻，无据。门类应期查表：行人类首选逢值，戌日取中。trigger 按六爻例填列。", 0.57, T(True, False, False, "终局主坐标兼取变爻未土之逢值续验，变卦夬之结构参与定归期故 changed_main；父母明现无伏神；读法无争议注记"))
P["LY-003"] = ("子病凶 negative（终局单判）：占子病，地风升静卦、子孙午火伏于世爻妻财丑土之下，酉月丙辰日午火休囚、伏神被丑合绊又遭辰土泄，主用神伏藏难出、病终凶危难愈。应期双层：危期窗口旬内，主坐标取午日（伏神逢值而出、出而受克更危），次取辰日。对象复述：主语为患病之子，伏藏子孙即其人。", "占子病一题，卦地风升静卦、子孙午火伏藏先行；tradition=liuyao（卡面逐字）；用神伏藏必须借伏神作断：飞神丑土为妻财、合绊午火且辰日泄火，子孙原神寅木虽在应爻妻财丑下不生（应爻丑土非木），源断；静卦无动化，定性以伏神受绊为主，反转条件为逢寅午冲飞之日出伏得救——窗口内午日出而仍受月克，故只作危点不作救点。门类应期查表：病占首选伏神逢值定危，午日取中。双闸已过。", 0.58, T(False, True, False, "子孙午火伏于世爻妻财丑土之下，全断系于伏神故 reserve_used；静卦读法卡面无争议"))
P["LY-004"] = ("父病不治 negative（终局单判）：一家四占同指一事——复卦父母巳火伏于官鬼寅木之下、损卦父母巳火现于初爻、渐卦父母午火动化妻财亥水（化回头克），三路同指父母爻受克无救，主父病必危、终不治。应期双层：危期窗口旬内，主坐标取巳日（父母逢值），午日为动化逢值之续危。对象复述：四卦主语同为患病之父，逐卦父母爻指代同一人。", "占父病一题，四度占卜三卦并陈（复、损、渐之巽）先行；tradition=liuyao（卡面逐字）；卯月丙辰日，复卦巳火伏于寅木鬼下受生而泄于月木、终被辰土晦，损卦巳火初爻无援，渐卦午火父母动化亥水回头克为决定性凶据；动化方向：午化亥回头克向凶；反转条件：父母得日月生扶脱克则翻，四卦无一有此据故不翻。多占同断按 skill 一事一占复盘口径合参，不作四事。门类应期查表：病占危期首选父母逢值，巳日取中。", 0.62, T(True, False, False, "渐卦父母午火动化亥水回头克为终局决定据、变卦巽之结构参与定断故 changed_main；复卦虽涉伏神父母，本终局主据在渐卦动化而非伏神，故 reserve_used 不取；四卦读法卡面无争议注记"))
P["LY-005"] = ("乡试必中 positive（终局单判）：占乡试，雷风恒之泽风大过，五爻官鬼申金动化酉金进神，申月癸卯日官星临月旺动而化进，主功名发动、今科必中，且名次不低。应期双层：窗口以月档计（科试放榜尺度），主坐标取酉月酉日进神逢值一线。", "占乡试一题，卦雷风恒之泽风大过、五爻官鬼申金ㄨ动先行；tradition=liuyao（卡面逐字）；考试门以官鬼为功名、父母为文书：官鬼申金临申月当令、动化酉金为进神主步步高进，父母亥水居三爻得申金动生，官印相生链完整；动化方向：申化酉进神向吉足级；反转条件：官星化破或父母受冲则翻，无据。门类应期查表：功名门首选官星化进逢值，酉位取中，闸门无空墓待释。双闸与二路复推已过。", 0.63, T(True, False, False, "官鬼动化进神、变卦大过之官星酉金参与定终局故 changed_main；官印俱明现无伏神；读法无争议"))
P["LY-006"] = ("求婚可成 positive（终局单判）：山火贲之水地比，四爻并动而妻财未土持世发动、化戌土进位，财临世身主婚事就我，子孙巳火动生财、父母子水动化未土归财，主媒妁文书虽多周折终成。应期双层：窗口旬月之间，主坐标取未日（世财逢值），戌日为化爻续验。对象核对：应验对象为所求之婚与求婚者本人，妻财指代女方、世爻指代本人，两不相混。", "占求婚成否一题，卦山火贲之水地比、初四五上四爻并动先行；tradition=liuyao（卡面逐字）；卯月乙丑日妻财未土得丑日冲动、持世而动为婚主动就之象，官鬼酉金动化申金退主男方顾虑渐退不碍成，父母子水动化未土、文书终归于财；动化方向：世财未化戌土进向成；反转条件：财化破或世应相冲则翻，变卦比为六合主和合故不翻。门类应期查表：婚姻门首选世财逢值，未日取中。多爻并动读法卡面系据装卦推得卦名，已在此留痕惟不列 disputed（卡面未注争议）。", 0.56, T(True, False, False, "变卦比为六合、世财化戌进位共同定终局故 changed_main；妻财明现持世无伏神；卦名系卡面据装卦推得、非争议读法故 disputed 不取"))
P["LY-007"] = ("迎父可遇 positive（终局单判）：父已起程、我往迎之——水泽节之火泽睽，五爻父母戌土动化未土主父行已动，四爻世爻兄弟申金动化酉金主我行得进，子孙子水动化官鬼巳火为途遇之应，主途中可以相遇。应期双层：窗口数日内，主坐标取戌日（父母逢值、人至），次取申日我行逢值。对象复述：主语一方为归家之父（父母爻）、一方为往迎之占者（世爻），逐名对回不相混。", "占迎父遇否一题，卦水泽节之火泽睽、上五四三爻并动先行；tradition=liuyao（卡面逐字）；丑月丙戌日父母戌土临日动为父已起程之确据，世申金动化酉进主迎者行程顺遂，世应之间辰戌父母两现主两路相向；动化方向：戌化未退主父行渐近家门、申化酉进主迎者得进，两向相合成遇；反转条件：父母化空破则翻，无据。门类应期查表：行人迎候首选父母逢值，戌日正在日辰本日、取为窗口主坐标。卦名卡面注系据装卦推得，已留痕。", 0.57, T(True, False, False, "变卦睽之世应结构与父母化未共同定遇期故 changed_main；父母明现无伏神；读法无争议注记"))
P["LY-008"] = ("病渐退可愈 positive（终局单判）：占病，泽天夬之雷天大壮，五爻子孙酉金持世动化申金退神——子孙为药神制鬼，动化退神在此主病势渐退，主病可愈、按退势缓缓而痊。应期双层：窗口旬内，主坐标取酉日（药神逢值），申日为化爻退尽之续验。对象复述：主语为抱危症占病之本人，世爻子孙即其医药与本元指代。", "占病一题，卦泽天夬之雷天大壮、五爻子孙酉金○世动先行；此卡以 id 立目、卡面未标注 tradition 字段，按题面体裁自决：六爻纳甲病占断；申月辛卯日子孙酉金临月令余气、得月生而动，官鬼寅木应爻受卯日冲暗动却被酉金世动所克，药神制鬼链成立；动化方向：酉化申退神——病占退神有两读（药力退／病势退），以鬼受克、世临药神之全链取病势退读，另一读已在 reasoning 并列留痕；反转条件：寅鬼得日生旺脱克则翻，无据。门类应期查表：病占愈期首选用神（子孙）逢值，酉日取中。卡面出处为进神退神章，此章义理即本断所据。", 0.55, T(True, False, True, "子孙化退神、变卦大壮结构参与定愈势故 changed_main；子孙明现持世无伏神；退神两读（病退／药退）卡面章题下读法有分歧故 disputed 并已在 basis 并列两读"))
_seg6 = [k for k in P if k.startswith(("LR3", "LY"))]
assert len(_seg6) == 20, ("B06 count", len(_seg6))
print("segment B06 ok", len(P))
# ---------------- write out ----------------
BATCHES = json.loads((BASE / "runs/round71/batches.json").read_text())
IDS = BATCHES["B04"] + BATCHES["B05"] + BATCHES["B06"]
assert len(IDS) == 60, len(IDS)
assert set(P.keys()) == set(IDS), (set(IDS) ^ set(P.keys()))
for cid in IDS:
    pt, bs, cf, tg = P[cid]
    assert 0.0 <= cf <= 1.0 and pt and bs
    assert set(tg.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    rec = {"case_id": cid, "prediction_text": pt, "basis": bs, "confidence": cf, "trigger": tg}
    (OUT / f"{cid}.json").write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
written = 0
for cid in IDS:
    p = OUT / f"{cid}.json"
    d = json.loads(p.read_text(encoding="utf-8"))
    assert d["case_id"] == cid and set(d.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}
    written += 1
cm = sum(1 for c in IDS if P[c][3]["changed_main"]); ru = sum(1 for c in IDS if P[c][3]["reserve_used"]); di = sum(1 for c in IDS if P[c][3]["disputed"])
print("WROTE", written, "trigger counts changed_main/reserve_used/disputed =", cm, ru, di)
